SELECT CURRENT_TIMESTAMP() AS checked_at_utc, 'baseline' AS version,OrderItem,Period,InvoiceNo,ExpectedReceived,ActualReceived,InterestEIRThisPeriod,PrincipleThisPeriod,PrincipleEIRThisPeriod,PaymentDate FROM `pacific-plating-282708._script4f06476e8de4bc85e3fcd9aa533fc6d797e4adf1.baseline_dashboard` WHERE (OrderItem='L77084511-V1' AND Period=3) OR (OrderItem='L77829701-V1' AND Period=6)
UNION ALL SELECT CURRENT_TIMESTAMP(),'candidate',OrderItem,Period,InvoiceNo,ExpectedReceived,ActualReceived,InterestEIRThisPeriod,PrincipleThisPeriod,PrincipleEIRThisPeriod,PaymentDate FROM `pacific-plating-282708._script437ae657b2356f03dd96effc1f4250fc8fb0a183.candidate_dashboard` WHERE (OrderItem='L77084511-V1' AND Period=3) OR (OrderItem='L77829701-V1' AND Period=6);
SELECT CURRENT_TIMESTAMP() AS checked_at_utc,COUNT(*) AS later_period_additional_rows,COUNTIF(ABS(PrincipleThisPeriod-ActualReceived)>0.005) AS principle_differs_from_charge,COUNTIF(ABS(PrincipleEIRThisPeriod-ActualReceived)>0.005) AS principle_eir_differs_from_charge FROM `pacific-plating-282708._script437ae657b2356f03dd96effc1f4250fc8fb0a183.candidate_newpayment` WHERE ExpectedReceived=0 AND ActualReceived>0 AND Period>1;
SELECT CURRENT_TIMESTAMP() AS checked_at_utc,oi.human_id AS OrderItem,c.id,c.third_party_id,c.installment_number,c.amount,c.create_time,c.update_time FROM `pacific-plating-282708.careos.carepay_charges` c JOIN `pacific-plating-282708.careos.careos_orders` o ON o.payment=CONCAT('transactions/',c.transaction_id) JOIN `pacific-plating-282708.careos.careos_order_items` oi ON oi.order_id=o.id WHERE oi.human_id IN ('L77084511-V1','L77829701-V1') AND c.status='SUCCESSFUL' AND c.service_provider='RABBIT_LENDING' AND c.installment_number IN (3,6) ORDER BY OrderItem,c.installment_number,c.create_time;
